struct atm_dev *atm_dev_lookup(int number)
{
	struct atm_dev *dev;

	mutex_lock(&atm_dev_mutex);
	dev = __atm_dev_lookup(number);
	if (dev && test_bit(ATM_DF_REMOVED, &dev->flags)) {
		atm_dev_put(dev);
		dev = NULL;
	}
	mutex_unlock(&atm_dev_mutex);
	return dev;
}

